import { homedir } from 'os';
import { join, basename, dirname } from 'path';
import { mkdirSync, existsSync, copyFileSync } from 'fs';

// Data storage paths
export const CMEM_DIR = join(homedir(), '.cmem');
export const DB_PATH = join(CMEM_DIR, 'sessions.db');
export const MODELS_DIR = join(CMEM_DIR, 'models');
export const BACKUPS_DIR = join(CMEM_DIR, 'backups');

// Claude Code paths
export const CLAUDE_DIR = join(homedir(), '.claude');
export const CLAUDE_PROJECTS_DIR = join(CLAUDE_DIR, 'projects');
export const CLAUDE_SESSIONS_DIR = join(CLAUDE_DIR, 'sessions');

// Embedding model settings (transformers.js)
export const EMBEDDING_MODEL = 'nomic-ai/nomic-embed-text-v1.5';
export const EMBEDDING_DIMENSIONS = 768;

// Text limits
export const MAX_EMBEDDING_CHARS = 8000;
export const MAX_MESSAGE_PREVIEW_CHARS = 500;
export const MAX_MESSAGES_FOR_CONTEXT = 20;

// Database maintenance thresholds
export const DB_SIZE_ALERT_THRESHOLD = 5 * 1024 * 1024 * 1024; // 5GB
export const DEFAULT_PURGE_DAYS = 30;

// Ensure cmem directory exists
export function ensureCmemDir(): void {
  if (!existsSync(CMEM_DIR)) {
    mkdirSync(CMEM_DIR, { recursive: true });
  }
}

// Ensure models directory exists
export function ensureModelsDir(): void {
  ensureCmemDir();
  if (!existsSync(MODELS_DIR)) {
    mkdirSync(MODELS_DIR, { recursive: true });
  }
}

// Ensure backups directory exists
export function ensureBackupsDir(): void {
  ensureCmemDir();
  if (!existsSync(BACKUPS_DIR)) {
    mkdirSync(BACKUPS_DIR, { recursive: true });
  }
}

/**
 * Get the backup path for a Claude session file
 * Mirrors the Claude directory structure: ~/.cmem/backups/<project-dir>/<session>.jsonl
 */
export function getBackupPath(sourceFile: string): string {
  const projectDir = basename(dirname(sourceFile));
  const sessionFile = basename(sourceFile);
  return join(BACKUPS_DIR, projectDir, sessionFile);
}

/**
 * Backup a session JSONL file
 * Creates the project directory in backups if needed
 */
export function backupSessionFile(sourceFile: string): boolean {
  try {
    if (!existsSync(sourceFile)) return false;

    ensureBackupsDir();
    const backupPath = getBackupPath(sourceFile);
    const backupDir = dirname(backupPath);

    if (!existsSync(backupDir)) {
      mkdirSync(backupDir, { recursive: true });
    }

    copyFileSync(sourceFile, backupPath);
    return true;
  } catch {
    return false;
  }
}

/**
 * Check if a backup exists for a session
 */
export function hasBackup(sourceFile: string): boolean {
  const backupPath = getBackupPath(sourceFile);
  return existsSync(backupPath);
}

/**
 * Restore a session from backup to Claude's directory
 * Returns true if restored successfully
 */
export function restoreFromBackup(sourceFile: string): boolean {
  try {
    const backupPath = getBackupPath(sourceFile);
    if (!existsSync(backupPath)) return false;

    const sourceDir = dirname(sourceFile);
    if (!existsSync(sourceDir)) {
      mkdirSync(sourceDir, { recursive: true });
    }

    copyFileSync(backupPath, sourceFile);
    return true;
  } catch {
    return false;
  }
}
