/**
 * Lessons Database Operations
 *
 * CRUD operations for lessons and synthesis queue.
 */

import { randomUUID } from 'crypto';
import { getDatabase } from './index.js';
import type {
  Lesson,
  CreateLessonInput,
  UpdateLessonInput,
  LessonCategory,
  LessonSearchOptions,
  LessonFeedback,
  SynthesisQueueItem,
} from '../learning/types.js';

// ==================== LESSON ROW MAPPING ====================

interface LessonRow {
  id: string;
  project_path: string;
  category: LessonCategory;
  title: string;
  trigger_context: string;
  insight: string;
  reasoning: string | null;
  confidence: number;
  times_applied: number;
  times_validated: number;
  times_rejected: number;
  source_session_id: string | null;
  source_type: string;
  archived: number;
  created_at: string;
  updated_at: string;
  last_applied_at: string | null;
}

function mapLessonRow(row: LessonRow): Lesson {
  return {
    id: row.id,
    projectPath: row.project_path,
    category: row.category,
    title: row.title,
    triggerContext: row.trigger_context,
    insight: row.insight,
    reasoning: row.reasoning ?? undefined,
    confidence: row.confidence,
    timesApplied: row.times_applied,
    timesValidated: row.times_validated,
    timesRejected: row.times_rejected,
    sourceSessionId: row.source_session_id ?? undefined,
    sourceType: row.source_type as Lesson['sourceType'],
    archived: row.archived === 1,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    lastAppliedAt: row.last_applied_at ?? undefined,
  };
}

// ==================== LESSON CRUD ====================

/**
 * Create a new lesson
 */
export function createLesson(input: CreateLessonInput): Lesson {
  const db = getDatabase();
  const id = randomUUID();
  const now = new Date().toISOString();

  db.prepare(`
    INSERT INTO lessons (
      id, project_path, category, title, trigger_context, insight,
      reasoning, confidence, source_session_id, source_type,
      created_at, updated_at
    )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).run(
    id,
    input.projectPath,
    input.category,
    input.title,
    input.triggerContext,
    input.insight,
    input.reasoning ?? null,
    input.confidence ?? 0.5,
    input.sourceSessionId ?? null,
    input.sourceType ?? 'synthesized',
    now,
    now
  );

  return getLesson(id)!;
}

/**
 * Update an existing lesson
 */
export function updateLesson(id: string, updates: UpdateLessonInput): Lesson | null {
  const db = getDatabase();
  const now = new Date().toISOString();

  const fields: string[] = ['updated_at = ?'];
  const values: unknown[] = [now];

  if (updates.category !== undefined) {
    fields.push('category = ?');
    values.push(updates.category);
  }
  if (updates.title !== undefined) {
    fields.push('title = ?');
    values.push(updates.title);
  }
  if (updates.triggerContext !== undefined) {
    fields.push('trigger_context = ?');
    values.push(updates.triggerContext);
  }
  if (updates.insight !== undefined) {
    fields.push('insight = ?');
    values.push(updates.insight);
  }
  if (updates.reasoning !== undefined) {
    fields.push('reasoning = ?');
    values.push(updates.reasoning);
  }
  if (updates.confidence !== undefined) {
    fields.push('confidence = ?');
    values.push(updates.confidence);
  }
  if (updates.archived !== undefined) {
    fields.push('archived = ?');
    values.push(updates.archived ? 1 : 0);
  }

  values.push(id);

  db.prepare(`
    UPDATE lessons SET ${fields.join(', ')} WHERE id = ?
  `).run(...values);

  return getLesson(id);
}

/**
 * Delete a lesson
 */
export function deleteLesson(id: string): boolean {
  const db = getDatabase();

  const transaction = db.transaction(() => {
    // Delete embedding
    db.prepare('DELETE FROM lesson_embeddings WHERE lesson_id = ?').run(id);
    // Delete feedback
    db.prepare('DELETE FROM lesson_feedback WHERE lesson_id = ?').run(id);
    // Delete lesson
    const result = db.prepare('DELETE FROM lessons WHERE id = ?').run(id);
    return result.changes > 0;
  });

  return transaction();
}

/**
 * Archive a lesson (soft delete)
 */
export function archiveLesson(id: string): void {
  const db = getDatabase();
  db.prepare(`
    UPDATE lessons SET archived = 1, updated_at = ? WHERE id = ?
  `).run(new Date().toISOString(), id);
}

/**
 * Unarchive a lesson
 */
export function unarchiveLesson(id: string): void {
  const db = getDatabase();
  db.prepare(`
    UPDATE lessons SET archived = 0, updated_at = ? WHERE id = ?
  `).run(new Date().toISOString(), id);
}

/**
 * Get a lesson by ID
 */
export function getLesson(id: string): Lesson | null {
  const db = getDatabase();
  const row = db.prepare(`
    SELECT * FROM lessons WHERE id = ?
  `).get(id) as LessonRow | undefined;

  return row ? mapLessonRow(row) : null;
}

/**
 * Get lessons by project path with filtering options
 */
export function getLessonsByProject(
  projectPath: string,
  options: LessonSearchOptions = {}
): Lesson[] {
  const db = getDatabase();

  let query = 'SELECT * FROM lessons WHERE project_path = ?';
  const params: unknown[] = [projectPath];

  if (options.category) {
    query += ' AND category = ?';
    params.push(options.category);
  }

  if (options.archived !== undefined) {
    query += ' AND archived = ?';
    params.push(options.archived ? 1 : 0);
  } else {
    // Default to non-archived
    query += ' AND archived = 0';
  }

  if (options.minConfidence !== undefined) {
    query += ' AND confidence >= ?';
    params.push(options.minConfidence);
  }

  query += ' ORDER BY confidence DESC, times_applied DESC';

  if (options.limit) {
    query += ' LIMIT ?';
    params.push(options.limit);
  }

  const rows = db.prepare(query).all(...params) as LessonRow[];
  return rows.map(mapLessonRow);
}

/**
 * Get core lessons - high confidence, frequently validated
 */
export function getCoreLessons(projectPath: string, limit: number = 3): Lesson[] {
  const db = getDatabase();

  const rows = db.prepare(`
    SELECT * FROM lessons
    WHERE project_path = ?
      AND archived = 0
      AND confidence >= 0.7
    ORDER BY
      times_validated DESC,
      confidence DESC,
      times_applied DESC
    LIMIT ?
  `).all(projectPath, limit) as LessonRow[];

  return rows.map(mapLessonRow);
}

/**
 * Get all lessons (for admin/debugging)
 */
export function getAllLessons(options: LessonSearchOptions = {}): Lesson[] {
  const db = getDatabase();

  let query = 'SELECT * FROM lessons WHERE 1=1';
  const params: unknown[] = [];

  if (options.category) {
    query += ' AND category = ?';
    params.push(options.category);
  }

  if (options.archived !== undefined) {
    query += ' AND archived = ?';
    params.push(options.archived ? 1 : 0);
  }

  if (options.minConfidence !== undefined) {
    query += ' AND confidence >= ?';
    params.push(options.minConfidence);
  }

  query += ' ORDER BY updated_at DESC';

  if (options.limit) {
    query += ' LIMIT ?';
    params.push(options.limit);
  }

  const rows = db.prepare(query).all(...params) as LessonRow[];
  return rows.map(mapLessonRow);
}

// ==================== LESSON APPLICATION/FEEDBACK ====================

/**
 * Record that a lesson was applied (shown to user)
 */
export function recordLessonApplication(id: string): void {
  const db = getDatabase();
  const now = new Date().toISOString();

  db.prepare(`
    UPDATE lessons
    SET times_applied = times_applied + 1,
        last_applied_at = ?,
        updated_at = ?
    WHERE id = ?
  `).run(now, now, id);
}

/**
 * Record validation feedback for a lesson
 */
export function recordLessonValidation(id: string, sessionId?: string, comment?: string): void {
  const db = getDatabase();
  const now = new Date().toISOString();

  const transaction = db.transaction(() => {
    // Update lesson counter
    db.prepare(`
      UPDATE lessons
      SET times_validated = times_validated + 1, updated_at = ?
      WHERE id = ?
    `).run(now, id);

    // Record feedback
    db.prepare(`
      INSERT INTO lesson_feedback (lesson_id, session_id, feedback_type, comment)
      VALUES (?, ?, 'validated', ?)
    `).run(id, sessionId ?? null, comment ?? null);
  });

  transaction();
}

/**
 * Record rejection feedback for a lesson
 */
export function recordLessonRejection(id: string, sessionId?: string, comment?: string): void {
  const db = getDatabase();
  const now = new Date().toISOString();

  const transaction = db.transaction(() => {
    // Update lesson counter
    db.prepare(`
      UPDATE lessons
      SET times_rejected = times_rejected + 1, updated_at = ?
      WHERE id = ?
    `).run(now, id);

    // Record feedback
    db.prepare(`
      INSERT INTO lesson_feedback (lesson_id, session_id, feedback_type, comment)
      VALUES (?, ?, 'rejected', ?)
    `).run(id, sessionId ?? null, comment ?? null);
  });

  transaction();
}

/**
 * Get feedback for a lesson
 */
export function getLessonFeedback(lessonId: string): LessonFeedback[] {
  const db = getDatabase();

  const rows = db.prepare(`
    SELECT
      id,
      lesson_id as lessonId,
      session_id as sessionId,
      feedback_type as feedbackType,
      comment,
      created_at as createdAt
    FROM lesson_feedback
    WHERE lesson_id = ?
    ORDER BY created_at DESC
  `).all(lessonId) as LessonFeedback[];

  return rows;
}

// ==================== LESSON EMBEDDINGS ====================

/**
 * Store embedding for a lesson
 */
export function storeLessonEmbedding(lessonId: string, embedding: number[]): void {
  const db = getDatabase();

  // Delete existing embedding if any
  db.prepare('DELETE FROM lesson_embeddings WHERE lesson_id = ?').run(lessonId);

  // Insert new embedding
  db.prepare(`
    INSERT INTO lesson_embeddings (lesson_id, embedding)
    VALUES (?, ?)
  `).run(lessonId, JSON.stringify(embedding));
}

/**
 * Lesson with similarity distance (lower is more similar)
 */
export interface LessonWithDistance {
  lesson: Lesson;
  distance: number;
}

/**
 * Search lessons by embedding similarity
 */
export function searchLessonsByEmbedding(
  embedding: number[],
  projectPath: string,
  limit: number = 5
): Lesson[] {
  return searchLessonsByEmbeddingWithDistance(embedding, projectPath, limit)
    .map(r => r.lesson);
}

/**
 * Search lessons by embedding similarity, returning distance scores
 * Distance is L2 (Euclidean) - lower is more similar
 */
export function searchLessonsByEmbeddingWithDistance(
  embedding: number[],
  projectPath: string,
  limit: number = 5
): LessonWithDistance[] {
  const db = getDatabase();

  // Use sqlite-vec for vector similarity search
  const rows = db.prepare(`
    SELECT
      l.*,
      le.distance
    FROM lesson_embeddings le
    JOIN lessons l ON l.id = le.lesson_id
    WHERE l.project_path = ?
      AND l.archived = 0
      AND le.embedding MATCH ?
    ORDER BY le.distance ASC
    LIMIT ?
  `).all(projectPath, JSON.stringify(embedding), limit) as (LessonRow & { distance: number })[];

  return rows.map(row => ({
    lesson: mapLessonRow(row),
    distance: row.distance,
  }));
}

/**
 * Search lessons globally by embedding (across all projects)
 */
export function searchAllLessonsByEmbedding(
  embedding: number[],
  limit: number = 10
): Lesson[] {
  const db = getDatabase();

  const rows = db.prepare(`
    SELECT
      l.*,
      le.distance
    FROM lesson_embeddings le
    JOIN lessons l ON l.id = le.lesson_id
    WHERE l.archived = 0
      AND le.embedding MATCH ?
    ORDER BY le.distance ASC
    LIMIT ?
  `).all(JSON.stringify(embedding), limit) as (LessonRow & { distance: number })[];

  return rows.map(row => mapLessonRow(row));
}

// ==================== SYNTHESIS QUEUE ====================

/**
 * Queue a session for synthesis
 */
export function queueForSynthesis(sessionId: string, projectPath: string): void {
  const db = getDatabase();
  const now = new Date().toISOString();

  db.prepare(`
    INSERT OR REPLACE INTO synthesis_queue (session_id, project_path, queued_at, status)
    VALUES (?, ?, ?, 'pending')
  `).run(sessionId, projectPath, now);
}

/**
 * Get pending synthesis queue items
 */
export function getPendingSynthesis(limit: number = 5): SynthesisQueueItem[] {
  const db = getDatabase();

  const rows = db.prepare(`
    SELECT
      id,
      session_id as sessionId,
      project_path as projectPath,
      queued_at as queuedAt,
      status,
      processed_at as processedAt,
      lessons_created as lessonsCreated,
      error
    FROM synthesis_queue
    WHERE status = 'pending'
    ORDER BY queued_at ASC
    LIMIT ?
  `).all(limit) as SynthesisQueueItem[];

  return rows;
}

/**
 * Mark synthesis as in progress
 */
export function markSynthesisProcessing(id: number): void {
  const db = getDatabase();
  db.prepare(`
    UPDATE synthesis_queue SET status = 'processing' WHERE id = ?
  `).run(id);
}

/**
 * Mark synthesis as complete
 */
export function markSynthesisComplete(id: number, lessonsCreated: number): void {
  const db = getDatabase();
  const now = new Date().toISOString();

  db.prepare(`
    UPDATE synthesis_queue
    SET status = 'completed', processed_at = ?, lessons_created = ?
    WHERE id = ?
  `).run(now, lessonsCreated, id);
}

/**
 * Mark synthesis as failed
 */
export function markSynthesisFailed(id: number, error: string): void {
  const db = getDatabase();
  const now = new Date().toISOString();

  db.prepare(`
    UPDATE synthesis_queue
    SET status = 'failed', processed_at = ?, error = ?
    WHERE id = ?
  `).run(now, error, id);
}

/**
 * Get synthesis queue stats
 */
export function getSynthesisStats(): {
  pending: number;
  processing: number;
  completed: number;
  failed: number;
  totalLessonsCreated: number;
} {
  const db = getDatabase();

  const pending = (db.prepare(`
    SELECT COUNT(*) as count FROM synthesis_queue WHERE status = 'pending'
  `).get() as { count: number }).count;

  const processing = (db.prepare(`
    SELECT COUNT(*) as count FROM synthesis_queue WHERE status = 'processing'
  `).get() as { count: number }).count;

  const completed = (db.prepare(`
    SELECT COUNT(*) as count FROM synthesis_queue WHERE status = 'completed'
  `).get() as { count: number }).count;

  const failed = (db.prepare(`
    SELECT COUNT(*) as count FROM synthesis_queue WHERE status = 'failed'
  `).get() as { count: number }).count;

  const totalLessonsCreated = (db.prepare(`
    SELECT COALESCE(SUM(lessons_created), 0) as total FROM synthesis_queue WHERE status = 'completed'
  `).get() as { total: number }).total;

  return { pending, processing, completed, failed, totalLessonsCreated };
}

// ==================== LESSON STATS ====================

/**
 * Get lesson statistics
 */
export function getLessonStats(): {
  totalLessons: number;
  activeLessons: number;
  archivedLessons: number;
  byCategory: Record<LessonCategory, number>;
  avgConfidence: number;
} {
  const db = getDatabase();

  const totalLessons = (db.prepare(`
    SELECT COUNT(*) as count FROM lessons
  `).get() as { count: number }).count;

  const activeLessons = (db.prepare(`
    SELECT COUNT(*) as count FROM lessons WHERE archived = 0
  `).get() as { count: number }).count;

  const archivedLessons = totalLessons - activeLessons;

  const categoryRows = db.prepare(`
    SELECT category, COUNT(*) as count
    FROM lessons
    WHERE archived = 0
    GROUP BY category
  `).all() as { category: LessonCategory; count: number }[];

  const byCategory: Record<LessonCategory, number> = {
    architecture_decision: 0,
    anti_pattern: 0,
    bug_pattern: 0,
    project_convention: 0,
    dependency_knowledge: 0,
    domain_knowledge: 0,
    workflow: 0,
    other: 0,
  };

  for (const row of categoryRows) {
    byCategory[row.category] = row.count;
  }

  const avgConfidence = (db.prepare(`
    SELECT COALESCE(AVG(confidence), 0) as avg FROM lessons WHERE archived = 0
  `).get() as { avg: number }).avg;

  return {
    totalLessons,
    activeLessons,
    archivedLessons,
    byCategory,
    avgConfidence,
  };
}

/**
 * Get queue status (alias for getSynthesisStats)
 */
export function getQueueStatus() {
  return getSynthesisStats();
}

// ==================== SESSION INJECTION CACHE ====================

/**
 * Get lesson IDs that have already been injected in this session
 */
export function getInjectedLessonIds(sessionId: string): Set<string> {
  const db = getDatabase();

  const rows = db.prepare(`
    SELECT lesson_id FROM session_injections WHERE session_id = ?
  `).all(sessionId) as { lesson_id: string }[];

  return new Set(rows.map(row => row.lesson_id));
}

/**
 * Record that lessons were injected in a session
 */
export function recordInjectedLessons(sessionId: string, lessonIds: string[]): void {
  if (lessonIds.length === 0) return;

  const db = getDatabase();
  const now = new Date().toISOString();

  const stmt = db.prepare(`
    INSERT OR IGNORE INTO session_injections (session_id, lesson_id, injected_at)
    VALUES (?, ?, ?)
  `);

  const transaction = db.transaction(() => {
    for (const lessonId of lessonIds) {
      stmt.run(sessionId, lessonId, now);
    }
  });

  transaction();
}

/**
 * Clear injection cache for a session (e.g., on compaction)
 */
export function clearSessionInjections(sessionId: string): void {
  const db = getDatabase();
  db.prepare('DELETE FROM session_injections WHERE session_id = ?').run(sessionId);
}

/**
 * Clean up old session injection records (sessions older than N days)
 */
export function cleanupOldInjections(daysOld: number = 7): number {
  const db = getDatabase();
  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - daysOld);

  const result = db.prepare(`
    DELETE FROM session_injections WHERE injected_at < ?
  `).run(cutoff.toISOString());

  return result.changes;
}

/**
 * Get distinct project paths from lessons
 */
export function getDistinctProjects(): string[] {
  const db = getDatabase();

  const rows = db.prepare(`
    SELECT DISTINCT project_path
    FROM lessons
    WHERE project_path IS NOT NULL AND project_path != ''
    ORDER BY project_path ASC
  `).all() as { project_path: string }[];

  return rows.map(row => row.project_path);
}
