/**
 * Session Sync Hook
 *
 * Called on Stop and PreCompact events to sync the current session.
 * After syncing, spawns a background process to synthesize lessons.
 */

import { statSync, existsSync, readFileSync, readdirSync } from 'fs';
import { join, dirname, basename } from 'path';
import { spawn } from 'child_process';
import { fileURLToPath } from 'url';
import { parseSessionFile, generateSummary, ParsedMessage, extractSessionMetadata, isAutomatedByContent } from '../parser/index.js';
import {
  createSession,
  getSessionBySourceFile,
  updateSession,
  needsReembedding,
  updateEmbeddingState,
} from '../db/sessions.js';
import { storeEmbedding } from '../db/vectors.js';
import { getEmbedding, createEmbeddingText, initializeEmbeddings, isReady } from '../embeddings/index.js';
import { generateTitle } from '../utils/format.js';
import { backupSessionFile, CLAUDE_PROJECTS_DIR } from '../utils/config.js';
import { queueForSynthesis, clearSessionInjections } from '../db/lessons.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

interface HookInput {
  session_id: string;
  cwd: string;
  transcript_path?: string;
}

interface SessionIndexEntry {
  sessionId: string;
  projectPath: string;
}

/**
 * Read stdin as JSON
 */
async function readStdin(): Promise<string> {
  return new Promise((resolve) => {
    let data = '';
    process.stdin.setEncoding('utf8');
    process.stdin.on('readable', () => {
      let chunk;
      while ((chunk = process.stdin.read()) !== null) {
        data += chunk;
      }
    });
    process.stdin.on('end', () => {
      resolve(data);
    });
    // If no stdin data after timeout, resolve with empty
    setTimeout(() => resolve(data), 100);
  });
}

/**
 * Spawn a detached background process to run synthesis
 * This allows the hook to exit quickly while synthesis runs in background
 */
function spawnBackgroundSynthesis(): void {
  try {
    // Path to synthesize.js is in the same directory as this hook
    const synthesizePath = join(__dirname, 'synthesize.js');

    if (!existsSync(synthesizePath)) {
      // Synthesize script not found, skip
      return;
    }

    // Spawn detached process that processes 1 session
    // Using 'node' directly since we're in a Node.js environment
    const child = spawn('node', [synthesizePath, '1'], {
      detached: true,
      stdio: 'ignore', // Don't inherit stdio
      env: { ...process.env },
    });

    // Allow parent process to exit independently
    child.unref();
  } catch {
    // Silently fail - synthesis can be run manually
  }
}

/**
 * Find session file from Claude's storage
 */
function findSessionFile(sessionId: string, cwd: string): string | null {
  // Try to find in projects directory based on cwd hash
  if (existsSync(CLAUDE_PROJECTS_DIR)) {
    const projectDirs = readdirSync(CLAUDE_PROJECTS_DIR);
    for (const projectDir of projectDirs) {
      const projectPath = join(CLAUDE_PROJECTS_DIR, projectDir);
      const sessionFile = join(projectPath, `${sessionId}.jsonl`);
      if (existsSync(sessionFile)) {
        return sessionFile;
      }
    }
  }

  return null;
}

/**
 * Get project path from sessions-index.json
 */
function getProjectPathFromIndex(filePath: string, sessionId: string): string | null {
  const projectDir = dirname(filePath);
  const indexPath = join(projectDir, 'sessions-index.json');

  if (!existsSync(indexPath)) return null;

  try {
    const content = readFileSync(indexPath, 'utf-8');
    const index = JSON.parse(content) as { entries: SessionIndexEntry[] };
    const entry = index.entries.find(e => e.sessionId === sessionId);
    return entry?.projectPath || null;
  } catch {
    return null;
  }
}

/**
 * Load messages from all subagent sessions for a parent session
 */
function loadSubagentMessages(projectDirPath: string, parentSessionId: string): ParsedMessage[] {
  const subagentsDir = join(projectDirPath, parentSessionId, 'subagents');
  if (!existsSync(subagentsDir)) return [];

  const messages: ParsedMessage[] = [];

  try {
    const agentFiles = readdirSync(subagentsDir).filter(f => f.endsWith('.jsonl'));
    for (const agentFile of agentFiles) {
      const agentPath = join(subagentsDir, agentFile);
      const agentMessages = parseSessionFile(agentPath);
      messages.push(...agentMessages);
    }
  } catch {
    // Ignore errors reading subagent files
  }

  return messages;
}

/**
 * Process a session file - sync to database and backup
 */
async function processSessionFile(
  filePath: string,
  embeddingsReady: boolean,
  embedThreshold: number = 500
): Promise<{ sessionId: string; isNew: boolean } | null> {
  try {
    // Parse the session file
    const messages = parseSessionFile(filePath);

    if (messages.length === 0) {
      return null;
    }

    // Get file stats
    const stats = statSync(filePath);
    const fileMtime = stats.mtime.toISOString();

    // Check if we already have this session
    const existingSession = getSessionBySourceFile(filePath);

    // Get session ID from filename
    const sessionIdFromFile = basename(filePath, '.jsonl');

    // Load agent messages for this session (for embeddings)
    const agentMessages = loadSubagentMessages(dirname(filePath), sessionIdFromFile);
    const allMessages = [...messages, ...agentMessages];

    // Calculate content length for embedding decisions (including agent messages)
    const contentLength = allMessages.reduce((sum, m) => sum + m.content.length, 0);

    // Generate title from first user message
    const firstUserMsg = messages.find(m => m.role === 'user');
    const title = firstUserMsg ? generateTitle(firstUserMsg.content) : 'Untitled Session';

    // Generate summary
    const summary = generateSummary(messages);

    // Build raw data for storage
    const rawData = JSON.stringify({ filePath, messages, mtime: fileMtime });

    // Get project path from sessions-index.json
    const projectPath = getProjectPathFromIndex(filePath, sessionIdFromFile);

    // Extract metadata (isSidechain, agentId, isMeta) from JSONL
    const metadata = extractSessionMetadata(filePath);
    // Mark as automated if: JSONL metadata says so, OR title matches automated patterns
    const isAutomated = metadata.isSidechain || metadata.isMeta || isAutomatedByContent(title);

    let sessionId: string;
    let isNew = false;

    if (existingSession) {
      // Update existing session
      sessionId = existingSession.id;

      // Update if content has changed
      if (existingSession.messageCount !== messages.length) {
        updateSession(sessionId, {
          title,
          summary,
          rawData,
          messages,
          isSidechain: metadata.isSidechain,
          isAutomated,
          projectPath: projectPath || undefined,
        });
      }
    } else {
      // Create new session
      isNew = true;
      sessionId = createSession({
        title,
        summary,
        projectPath,
        sourceFile: filePath,
        rawData,
        messages,
        isSidechain: metadata.isSidechain,
        isAutomated,
      });
    }

    // Handle embedding (include agent messages for better search)
    if (embeddingsReady) {
      const shouldEmbed = needsReembedding(sessionId, contentLength, embedThreshold);

      if (shouldEmbed) {
        try {
          // Use all messages including agents for richer embeddings
          const embeddingText = createEmbeddingText(title, summary, allMessages);
          const embedding = await getEmbedding(embeddingText);
          storeEmbedding(sessionId, embedding);
          updateEmbeddingState(sessionId, contentLength, fileMtime);
        } catch {
          // Embedding failed, continue without it
        }
      }
    }

    // Backup the JSONL file to cmem's storage (conversations never lost)
    backupSessionFile(filePath);

    return { sessionId, isNew };
  } catch {
    return null;
  }
}

async function main() {
  try {
    const stdinData = await readStdin();
    const input: HookInput = stdinData ? JSON.parse(stdinData) : {};

    // Find session file
    let sessionFile: string | null = null;

    if (input.transcript_path && existsSync(input.transcript_path)) {
      sessionFile = input.transcript_path;
    } else if (input.session_id && input.cwd) {
      sessionFile = findSessionFile(input.session_id, input.cwd);
    }

    if (!sessionFile) {
      process.exit(0);
    }

    // Initialize embeddings if possible
    let embeddingsReady = false;
    if (isReady()) {
      embeddingsReady = true;
    } else {
      try {
        await initializeEmbeddings();
        embeddingsReady = isReady();
      } catch {
        // Continue without embeddings
      }
    }

    // Process the session file
    const result = await processSessionFile(sessionFile, embeddingsReady);

    if (result) {
      // Get project path for synthesis queue
      const projectPath = getProjectPathFromIndex(sessionFile, result.sessionId) || input.cwd || '';

      // Queue for synthesis (will be processed later)
      try {
        queueForSynthesis(result.sessionId, projectPath);
        // Spawn background process to synthesize lessons
        spawnBackgroundSynthesis();
      } catch {
        // Synthesis queue may not exist yet, that's okay
      }
    }

    // Clear lesson injection cache for this session
    // On Stop: session is ending, cache doesn't matter
    // On PreCompact: context will be lost, lessons need to be re-injected
    if (input.session_id) {
      try {
        clearSessionInjections(input.session_id);
      } catch {
        // Ignore errors clearing cache
      }
    }

    process.exit(0);
  } catch {
    process.exit(1);
  }
}

main();
